const readyWorlds=new WeakSet();
/* The single store. `state` holds the browser campaign (Act 1 history, Act 2 career, elections) and `state.world`
 * holds the TypeScript engine's world (staff psychology, burnout, memory, careers, recruitment, voter groups).
 * The browser owns organisation metrics and mirrors them into the world before each engine step; the engine's
 * consequences come back as deltas and log entries, so no number is ticked twice. */
const GameEngine={
 get state(){return state;},
 api(){if(typeof RepublicEngine==="undefined")throw Error("The simulation engine did not load. Reload the page.");return RepublicEngine;},
 ensureWorld(){
  if(!state.player||!state.org)return;
  const api=this.api(),p=state.player;
  if(!state.world){
   const traitSkills=TRAIT_SKILLS[p.trait]||TRAIT_SKILLS.speaker;
   state.world=api.createBrowserWorld({name:p.name||"Citizen",age:Number(p.age)||30,homeState:p.state||"Delhi",profession:p.profession||"Citizen",trait:p.trait||"speaker",skills:p.skills||traitSkills,
    monthlyIncome:p.monthlyIncome??35000,monthlyLivingCosts:p.monthlyLivingCosts??22000,savings:p.money??0,seed:state.electionSeed??5432026,gender:p.gender,district:p.district,education:p.education,family:p.family});
   this.migrateAdvisers();
  }else if(!readyWorlds.has(state.world))state.world=api.hydrateWorld(state.world);
  readyWorlds.add(state.world);
 },
 /** Saves from before the engine was connected kept five template advisers; paid ones become engine colleagues. */
 migrateAdvisers(){
  if(!Array.isArray(state.advisers)||!state.org.staff||state.flags?.advisersMigrated)return;
  const w=state.world;
  state.advisers.slice(0,state.org.staff).forEach((adv,i)=>{
   const id=`adviser_${i+1}`;
   w.characters[id]={id,name:adv.name,age:31,role:adv.role,homeState:"Delhi",background:`Joined as the movement's ${adv.role.toLowerCase()} adviser.`,salaryMonthly:0,skills:{communication:55,strategy:55,field:55},
    energy:adv.energy??70,health:90,stress:adv.stress??20,morale:adv.morale??70,psychology:{ambition:55,integrity:65,greed:35,fear:30,ego:45,riskTolerance:50,ideologicalCommitment:60},employed:false,volunteer:false,joinedOn:"",unpaidStreak:0};
   this.api().executePeopleCommand(w,{type:"HIRE_CHARACTER",characterId:id,role:adv.role,salaryMonthly:15000,volunteer:false});
  });
  state.org.monthlyBurn=Math.max(6100,(state.org.monthlyBurn||0)-15000*state.org.staff);
  state.org.staff=0;state.flags.advisersMigrated=true;delete state.advisers;
 },
 sync(){this.ensureWorld();this.api().syncFromBrowser(state.world,{date:state.date,day:state.day,funds:state.org.funds,volunteers:state.org.volunteers,credibility:state.org.credibility,media:state.org.media,legal:state.org.legal,playerName:state.player.name,orgName:state.org.name});return state.world;},
 /** Applies an engine report: credibility moves by whole points and every career event enters the log. */
 absorb(report){
  if(report.credibilityDelta)state.org.credibility=clamp(state.org.credibility+Math.sign(report.credibilityDelta)*Math.ceil(Math.abs(report.credibilityDelta)));
  const titles={mistake:"Staff mistake",burnout_leave:"Burnout leave",resignation:"Resignation",skill_growth:"Skill growth",payroll_response:"Payroll response"};
  for(const e of report.events)if(e.type!=="skill_growth")record(titles[e.type]||"Team update",`${e.name}: ${e.note}`);
 },
 /** The engine's daily step, run after the browser has moved the date forward. */
 tick(previousDate){
  const api=this.api(),w=this.sync();
  this.absorb(api.dailyPeopleTick(w));
  if(previousDate.slice(0,7)!==state.date.slice(0,7)){
   const month=api.monthEnd(w,state.org.funds);state.org.funds=month.fundsAfter;
   if(month.due)record(month.shortfall?"Staff payroll shortfall":"Staff salaries paid",month.shortfall?`Only ₹${money(month.paid)} of ₹${money(month.due)} in salaries could be paid. Each colleague will respond in their own way.`:`₹${money(month.paid)} paid to the team.`);
   this.absorb(month);
  }
 },
 people(command){const result=this.api().executePeopleCommand(this.sync(),command);return result;},
 teamMorale(delta,note){if(!delta)return 0;return this.api().teamMoraleShift(this.sync(),delta,note);},
 useStaff(skill,intensity){return this.api().useStaff(this.sync(),skill,intensity);},
 save(){state.saveVersion=SAVE_VERSION;localStorage.setItem(SAVE_KEY,JSON.stringify(state));},
 /** Accepts a raw save, an export wrapper or a parsed object; the whole tree, engine world included, is restored. */
 load(raw){const data=typeof raw==="string"?JSON.parse(raw):raw;const imported=data&&data.state?data.state:data;if(!imported?.player?.name||!imported.org||!imported.date||!Number.isInteger(imported.day))throw Error("That is not a valid Republic 543 save.");state=imported;ensureState();expireStaleScenes();return state;},
 exportData(){return {format:"republic543",version:SAVE_VERSION,state};},
 /** Every UI control routes through here, so one place handles errors, saving and re-rendering. */
 dispatch(type,payload={}){
  const handler=ACTIONS[type];if(!handler)return toast("Unknown action.");
  // A click on the page asks first when the action changes the world; code, tests and the simulator do not.
  if(payload.fromUI&&needsConfirmation(type,payload))return confirmAction(type,payload,()=>handler(payload));
  try{return handler(payload);}catch(error){toast(error.message);}
 }
};
