/** Monthly household budget: salary depends on job standing; what savings cannot cover becomes debt and stress. */
function settlePersonalMonth(){const p=state.player,income=Math.round((p.monthlyIncome??35000)*(p.jobStanding??75)/100),costs=p.monthlyLivingCosts??22000,balance=(p.money||0)+income-costs;
 if(balance<0){p.debt=(p.debt||0)-balance;p.money=0;p.stress=clamp(p.stress+6);record("Household bills unpaid",`Savings could not cover ₹${money(costs)} in living costs. Personal debt is now ₹${money(p.debt)}.`);}
 else{const repay=Math.min(p.debt||0,balance);p.debt=(p.debt||0)-repay;p.money=balance-repay;if(repay)record("Debt repaid",`₹${money(repay)} went to personal debt${p.debt?`; ₹${money(p.debt)} remains`:" and cleared it"}.`);}}
let recovering=false;
/** Neglect has consequences: a lost job is announced once, and collapse forces three days away from the movement. */
function checkPersonalLimits(){const p=state.player;
 if(p.jobStanding<=0&&(p.monthlyIncome||0)>0&&!state.flags.jobLost){state.flags.jobLost=true;record("You lost your job","Too many missed shifts. There is no salary from now on; living costs come out of savings.");p.stress=clamp(p.stress+8);}
 if(p.health<=15&&!recovering){recovering=true;state.collapses=(state.collapses||0)+1;record("Collapse","Exhaustion put you in hospital for three days. The movement carried on without you.");applyEffect({media:-3,support:-1},"The team covered while you were in hospital.");GameEngine.teamMorale(-3,"Worried after the founder collapsed.");p.jobStanding=clamp(p.jobStanding-5);for(let i=0;i<3;i++)advanceDay();p.energy=55;p.stress=clamp(p.stress-25);p.health=clamp(p.health+30);recovering=false;}}
/** A historical dispatch left unanswered for three weeks closes itself: the moment passed without you. */
function expireStaleScenes(){const limit=addDays(state.date,-21);for(const id of [...state.pendingScenes]){const x=REAL_SCENES.find(v=>v.id===id);if(x&&x.date<limit){state.pendingScenes=state.pendingScenes.filter(v=>v!==id);state.sceneResponses[id]="No response: the moment passed";record("History moved on",`${x.title}: you did not respond, and the moment passed.`);}}}
function advanceDay(){ensureState();const previousDate=state.date,monthChanged=()=>previousDate.slice(0,7)!==state.date.slice(0,7);state.day++;const d=new Date(state.date+"T00:00:00Z");d.setUTCDate(d.getUTCDate()+1);state.date=d.toISOString().slice(0,10);if(state.historicalRoleplay&&!state.handoff&&previousDate<=timelineCutoff()&&state.date>timelineCutoff())state.pendingHandoff=true;expireStaleScenes();state.donorFatigue=Math.max(0,(state.donorFatigue||0)-5);for(const scene of REAL_SCENES){if(!scene.archive&&scene.date<=timelineCutoff()&&scene.date===state.date&&!state.sceneResponses[scene.id]&&!state.pendingScenes.includes(scene.id)){state.pendingScenes.push(scene.id);record("Historical dispatch",scene.title);}}state.player.energy=clamp(state.player.energy-3);state.player.stress=clamp(state.player.stress+1+(state.player.energy<30?2:0));if(state.org.volunteers>0)state.followers+=Math.round(state.org.media*2+state.org.volunteers*.3);state.player.level=1+Math.floor((state.day-1)/7);for(const x of state.projects.filter(v=>v.status==="active")){x.remaining--;if(x.remaining<=0){x.status="completed";applyEffect(x.effect);record("Operation completed",`${x.name} produced measurable results.`);}}if(monthChanged()){const m=state.macro;const govBoost=state.phase==="government"?(state.governance.publicServices-50)*.01:0;m.gdpGrowthPct=Math.round(Math.max(2,Math.min(9,m.gdpGrowthPct+(Math.random()-.5)*.4+govBoost))*100)/100;m.unemploymentPct=Math.round(Math.max(3,Math.min(14,m.unemploymentPct+(Math.random()-.5)*.3-govBoost))*100)/100;m.inflationPct=Math.round(Math.max(2,Math.min(11,m.inflationPct+(Math.random()-.5)*.4))*100)/100;m.populationM=Math.round((m.populationM+1.1)*10)/10;m.gdpTrillionUSD=Math.round(m.gdpTrillionUSD*(1+m.gdpGrowthPct/1200)*1000)/1000;
settlePersonalMonth();const due=state.org.monthlyBurn,paid=Math.min(due,state.org.funds);state.org.funds-=paid;if(paid<due){state.org.credibility=clamp(state.org.credibility-4);state.player.stress=clamp(state.player.stress+8);record("Operating shortfall",`Only ₹${money(paid)} of ₹${money(due)} in office, travel and tool costs could be paid.`);}else record("Monthly costs paid",`₹${money(due)} covered office, travel and tools.`);}if(state.date==="2026-07-25"&&!state.flags.reportedResignation){state.flags.reportedResignation=true;record("Historical anchor","The Education Minister resignation is reported. Your campaign trust and negotiating position remain consequences of your own decisions.");}if(state.player.energy<12){state.player.health=clamp(state.player.health-1);state.player.stress=clamp(state.player.stress+2);}
 for(const d of state.hiddenDeals){if(d.exposed)continue;d.exposureRisk=Math.min(92,d.exposureRisk+.6+state.org.media*.04);if(Math.random()*100<d.exposureRisk){d.exposed=true;d.exposedOn=state.date;applyEffect({credibility:-6,legal:14,media:12,support:-1});record("Undisclosed arrangement exposed",`A ₹${money(d.amount)} arrangement from ${safe(d.date)} surfaced. Credibility and legal exposure took a hit.`);}}
 GameEngine.tick(previousDate);
 resolveCivicDesk();
 if(state.org.prRetainer)state.org.credibility=clamp(state.org.credibility+.3);
 if(state.phase==="government"&&!state.pendingCrisis&&Math.random()<.08){const crisis=GOV_CRISES[Math.floor(Math.random()*GOV_CRISES.length)];state.pendingCrisis={id:crisis.id,offeredOn:state.date};record("National crisis",`${crisis.title} demands a response.`);}
 if(state.date>timelineCutoff()&&!state.pendingTip&&state.flags.firstResponse&&Math.random()<.06){const rival=RIVALS[Math.floor(Math.random()*RIVALS.length)];state.pendingTip={rivalId:rival.id,offeredOn:state.date};record("Anonymous tip received",`An insider says they have something on ${rival.name}.`);}
 checkPersonalLimits();
 resolveCampaignDeadlines();
 act3Daily();
 save();renderGame();}
function updateDate(){const d=new Date(state.date+"T00:00:00Z");$("#date-label").textContent=new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",year:"numeric",timeZone:"UTC"}).format(d).toUpperCase();const latest=state.history&&state.history[0];const breaking=latest&&latest.date===state.date&&/Expos|audit|Historical/.test(latest.title);$("#ticker-text").textContent=latest?`${latest.title.toUpperCase()} · ${latest.detail}`:`Day ${state.day}.`;}
/* A studio brief is intent, not a reward. The action settles its editorial effect after cost and energy guards pass. */
const committedApplyEffect=applyEffect;
applyEffect=(effect,note)=>{if(state?.lastMediaPlan?.date===state?.date&&!state.settlingEditorialPlan)return;return committedApplyEffect(effect,note);};
function launchPlannedOperation(id,approach){const project=PROJECTS.find(x=>x.id===id),started=state.day;if(!project)return;startPlannedProject(id,approach);const launched=state.projects[0]?.id===id?state.projects[0]:null;if(launched){state.operationFollowups??=[];if(!state.operationFollowups.some(x=>x.projectId===id&&x.started===started))state.operationFollowups.unshift({id:`review-${started}-${id}`,projectId:id,name:project.name,started,dueDay:started+project.days,approach:launched.approach});}}
function fileOperationReview(id,outcome){const review=(state.operationFollowups||[]).find(x=>x.id===id),choices={share:{title:"Hold a public debrief",effect:{media:2,credibility:1}},handover:{title:"Hand it to local organisers",effect:{volunteers:8,credibility:1}},audit:{title:"Publish a lessons note",effect:{legal:-2,credibility:2}}},choice=choices[outcome];if(!review||!choice)throw Error("That field report is no longer available.");applyEffect(choice.effect);state.operationFollowups=state.operationFollowups.filter(x=>x.id!==id);record("Operation follow-up",`${review.name}: ${choice.title}.`);save();renderPage();return choice;}
function startPlannedProject(id,approach="listen"){ensureState();const project=PROJECTS.find(x=>x.id===id);if(!project)return;if(state.org.funds<project.cost)return toast("The movement cannot afford this operation.");if(state.player.energy<project.energy)return toast("Your energy is too low. Rest before starting.");const plans={listen:{label:"Listen first",effect:{credibility:1}},deliver:{label:"Deliver visibly",effect:{support:1}},build:{label:"Build local capacity",effect:{volunteers:8}}},plan=plans[approach]||plans.listen,effect={...project.effect};for(const [key,value] of Object.entries(plan.effect))effect[key]=(effect[key]||0)+value;applyEffect({funds:-project.cost,energy:-project.energy});state.projects.unshift({id:project.id,name:project.name,date:state.date,cost:project.cost,status:"active",remaining:project.days,effect,approach:plan.label});record("Operation launched",`${project.name} began with the ${plan.label.toLowerCase()} plan.`);advanceDay();toast(`${project.name} launched. The plan will shape the completed report.`);}
function fmtNum(n){n=Math.round(n||0);return n>=1000000?(n/1000000).toFixed(1)+"M":n>=1000?(n/1000).toFixed(1)+"K":String(n);}
function money(n){return n>=10000000?(n/10000000).toFixed(2)+" Cr":n>=100000?(n/100000).toFixed(1)+" L":n.toLocaleString("en-IN")}
function fmtFollowers(){return state.followers>=1000000?(state.followers/1000000).toFixed(1)+"M":state.followers>=1000?(state.followers/1000).toFixed(1)+"K":state.followers}
function save(){GameEngine.save();}
let toastTimer;function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2400)}
function twoTone(h){const text=h.textContent.trim();const words=text.split(/\s+/);h.dataset.toned="1";if(words.length<2)return;const last=words.pop();h.innerHTML=words.join(" ")+' <span>'+last+"</span>";}
/* These controls deliberately open a decision room before an irreversible action. */
WIRING.push(["[data-act^='reel-']",b=>["studio",{kind:b.dataset.act}]]);
WIRING.push(["[data-act='interview']",()=>["studio",{kind:"interview"}]]);
WIRING.push(["[data-act='briefing'],[data-act='meme'],[data-act='thread'],[data-act='livestream'],[data-act='crisis-pr'],[data-act='pr-retainer']",b=>["mediaRoom",{kind:b.dataset.act}]]);
WIRING.push([["[data-review-operation]"].join(""),b=>["reviewOp",{id:b.dataset.reviewOperation}]]);
WIRING.push(["[data-field-incident]",b=>["fieldIncident",{id:b.dataset.fieldIncident}]]);
if(typeof MutationObserver!=="undefined"&&typeof document!=="undefined"&&document.body){new MutationObserver(()=>{document.querySelectorAll(".panel-title h3:not([data-toned]),.decision-box h2:not([data-toned])").forEach(twoTone);}).observe(document.body,{childList:true,subtree:true});}
init();
